import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from collections import defaultdict

MAX_DRIVERS = 2

def design(feats):
    # Calculate correlations and identify near-duplicates
    corr_matrix = np.corrcoef(feats.x.T)
    near_duplicates = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                near_duplicates.add((feats.ids[i], feats.ids[j]))

    # Find drivers using Welch's t-test
    drivers = []
    seen = set()

    # Sort features by effect size (mean_y1-mean_y0) 
    effect_sizes = []
    for i, fid in enumerate(feats.ids):
        mean_diff = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
        effect_sizes.append((abs(mean_diff), fid, i))

    effect_sizes.sort(reverse=True)

    # Select top drivers, avoiding near-duplicates
    for _, fid, idx in effect_sizes:
        if len(drivers) >= MAX_DRIVERS:
            break
        if fid in seen:
            continue

        # Check if any near-duplicate is already selected
        skip = False
        for dup_a, dup_b in near_duplicates:
            if (dup_a == fid and dup_b in drivers) or (dup_b == fid and dup_a in drivers):
                skip = True
                break

        if not skip:
            drivers.append(fid)
            seen.add(fid)

    # If no strong drivers found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build columns and products
    columns = list(drivers)
    products = []

    # Add interaction terms between drivers
    for i in range(len(drivers)):
        for j in range(i+1, len(drivers)):
            products.append((drivers[i], drivers[j]))

    # Create loadings for weighted score
    loadings = {}
    for fid in drivers:
        idx = feats.column(fid)
        # Use standardized coefficient from logistic regression as loading
        lr = LogisticRegression(penalty='l1', solver='liblinear')
        lr.fit(feats.x[:, [idx]], feats.y)
        loadings[fid] = lr.coef_[0][0]

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

